import AbstractProvider, { ProviderParams, EndpointArgument, ParseArgument, ProviderOptions, SearchResult, LatLng } from './provider';
export type RequestResult = {
    results: RawResult[];
    query: RawQuery[];
};
export interface RawResult {
    country: string;
    country_code: string;
    state: string;
    county: string;
    city: string;
    postcode: number;
    suburb: string;
    street: string;
    lon: string;
    lat: string;
    state_code: string;
    formatted: string;
    bbox?: BBox;
}
export interface RawQuery {
    text: string;
    parsed: RawQueryParsed;
}
export type RawQueryParsed = {
    city: string;
    expected_type: string;
};
export type BBox = {
    lon1: string;
    lat1: string;
    lon2: string;
    lat2: string;
};
export type GeoapifyProviderOptions = {
    searchUrl?: string;
    reverseUrl?: string;
} & ProviderOptions;
export default class GeoapifyProvider extends AbstractProvider<RequestResult, RawResult> {
    searchUrl: string;
    reverseUrl: string;
    constructor(options?: GeoapifyProviderOptions);
    endpoint({ query, type }: EndpointArgument): string;
    reverseParams({ lat, lng }: LatLng): ProviderParams;
    parse(response: ParseArgument<RequestResult>): SearchResult<RawResult>[];
}
